SELECT 
FROM tb_import_operation t
WHERE t.row_valid = 1
  AND t.domain = #{domain}
  AND t.active_import_id = #{importDataId}
LIMIT 1

SELECT COUNT(*)
FROM tb_import_operation t
WHERE t.operation_id = #{operationId}
  AND t.row_valid = 1
  AND t.lease_owner = #{owner}
  AND t.fence_token = #{fenceToken}
  AND t.lease_until >= #{now}
  AND t.status IN ('RUNNING', 'RECOVERING')
